// Sand: a box of sand you tip around. Every grain is a cell of a grid and
// falls the way the frame's accelerometer says down is
// (frameos.accelerometer(): gravity along the picture's axes), sliding off
// the grain under it to either side when it cannot fall straight. Lying flat,
// nothing moves; tipped, the sand runs. A shake throws it all up in the air.
// On a frame without an accelerometer, a swipe or an arrow key tips the box
// that way instead, and a key or the Action button shakes it.
//
// The grid is drawn with frameos.pixels, the 8-bit palette mode: a byte a
// cell, written straight into the panel, only the cells that changed. On a
// fast screen it runs as an animation; on e-paper the cells are bigger, a
// render runs ten steps at once, and the frame stops rendering once the sand
// has settled, until it is tipped again.
import { drawText, textWidth } from './font'
import { makePalette, WALL, TEXT } from './palette'

const EMPTY = 0
// The eight directions, clockwise from straight down: a grain falls along one,
// and slides along the two beside it.
const DX = [0, -1, -1, -1, 0, 1, 1, 1]
const DY = [1, 1, 0, -1, -1, -1, 0, 1]

// What outlives a render while the interpreter does; made again (and read
// back from `remember`) when it is gone.
let key = ''
let cols = 0
let rows = 0
let px = 1
let grid: Uint8Array = new Uint8Array(0)
let stamp: Uint8Array = new Uint8Array(0)
let out: Uint8Array = new Uint8Array(0)
let palette: Uint32Array = new Uint32Array(256)
let tick = 1
let rng = 1
let lastAt = 0
let startedAt = 0
let settled = false
let savedSettled = false
let lastDir = -1
// Down for a frame without an accelerometer: a direction index, 0 = down.
let tipped = 0
let pours: number[] = []
let tossAsked = false

const accelerometer = () => (typeof frameos.accelerometer === 'function' ? frameos.accelerometer() : null)

function random(): number {
  rng ^= rng << 13
  rng ^= rng >>> 17
  rng ^= rng << 5
  return rng >>> 0
}

function settings(app: any) {
  const scheme = String(app.config.colors || 'sand')
  return {
    colors: scheme === 'rainbow' || scheme === 'snow' ? scheme : 'sand',
    amount: Math.max(5, Math.min(70, Number(app.config.amount) || 35)),
  }
}

/** The walls: the border, and on a round panel everything outside the circle. */
function buildWalls(round: boolean) {
  const r = (Math.min(cols, rows) / 2) - 12 / px
  const cx = cols / 2
  const cy = rows / 2
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const i = y * cols + x
      const edge = x === 0 || y === 0 || x === cols - 1 || y === rows - 1
      const dx = x + 0.5 - cx
      const dy = y + 0.5 - cy
      grid[i] = edge || (round && dx * dx + dy * dy > r * r) ? WALL : EMPTY
    }
  }
}

/** Fills the bottom `amount` percent of the open cells with layered sand. */
function fill(amount: number, colors: string) {
  let open = 0
  for (let i = 0; i < grid.length; i++) if (grid[i] === EMPTY) open++
  let left = Math.floor((open * amount) / 100)
  for (let y = rows - 1; y >= 0 && left > 0; y--) {
    for (let x = 0; x < cols && left > 0; x++) {
      const i = y * cols + x
      if (grid[i] !== EMPTY) continue
      grid[i] = colorFor(colors, x, y)
      left--
    }
  }
}

/** A grain's color: bands of four tones, wavy, as sand in a bottle. */
function colorFor(colors: string, x: number, y: number): number {
  if (colors === 'rainbow') return 1 + Math.floor(((x + y * 0.5) / Math.max(4, cols / 6)) % 6)
  const wave = Math.sin(x / Math.max(3, cols / 8)) * 1.5
  const band = Math.floor((y + wave + (random() % 3) * 0.4) / Math.max(2, rows / 18))
  return 1 + (((band % 4) + 4) % 4)
}

function restore(saved: string): boolean {
  if (typeof saved !== 'string' || saved.length !== cols * rows) return false
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] === WALL) continue
    const v = saved.charCodeAt(i) - 48
    grid[i] = v > 0 && v < 10 ? v : EMPTY
  }
  return true
}

function save() {
  const codes: number[] = []
  const parts: string[] = []
  for (let i = 0; i < grid.length; i++) {
    const v = grid[i]
    codes.push(v === WALL ? 48 : 48 + v)
    if (codes.length === 1024) {
      parts.push(String.fromCharCode.apply(null, codes))
      codes.length = 0
    }
  }
  parts.push(String.fromCharCode.apply(null, codes))
  frameos.remember('sand', key + '|' + parts.join(''))
}

/** Which way down is this step: one of the eight directions, -1 when flat. */
function direction(gx: number, gy: number): number {
  const m = Math.sqrt(gx * gx + gy * gy)
  if (m < 0.12) return -1
  // The angle from straight down, clockwise, in eighths of a turn.
  let a = (Math.atan2(-gx, gy) / (Math.PI / 4) + 8) % 8
  const low = Math.floor(a)
  // Between two directions: one or the other, as often as it is nearer.
  const pick = (random() % 1000) / 1000 < a - low ? low + 1 : low
  return pick % 8
}

/** One step of the sand: each grain falls one cell, if it can. */
function step(dir: number, chance: number): number {
  tick = tick === 255 ? 1 : tick + 1
  const dx = DX[dir]
  const dy = DY[dir]
  const fall = dy * cols + dx
  const left = DY[(dir + 1) % 8] * cols + DX[(dir + 1) % 8]
  const right = DY[(dir + 7) % 8] * cols + DX[(dir + 7) % 8]
  // Square across the pull: where a grain on the surface rolls to when below
  // it is full, if it can go down from there. Without it a heap tipped by
  // 45 degrees stood still, at the steepest slope its eight neighbours allow.
  const sideA = DY[(dir + 2) % 8] * cols + DX[(dir + 2) % 8]
  const sideB = DY[(dir + 6) % 8] * cols + DX[(dir + 6) % 8]
  const g = grid
  const s = stamp
  const t = tick
  const w = cols
  const flip = (tick & 1) === 1
  let moved = 0
  // Grains nearest the floor first, so a column falls together.
  const y0 = dy > 0 ? rows - 2 : 1
  const y1 = dy > 0 ? 0 : rows - 1
  const ys = dy > 0 ? -1 : 1
  const backwards = dx > 0 || (dx === 0 && flip)
  const x0 = backwards ? w - 2 : 1
  const x1 = backwards ? 0 : w - 1
  const xs = backwards ? -1 : 1
  for (let y = y0; y !== y1; y += ys) {
    let i = y * w + x0
    for (let x = x0; x !== x1; x += xs, i += xs) {
      const v = g[i]
      if (v === 0 || v === WALL || s[i] === t) continue
      if (chance < 1000 && random() % 1000 >= chance) continue
      let to = i + fall
      if (g[to] !== 0) {
        const a = i + left
        const b = i + right
        const aFree = g[a] === 0
        const bFree = g[b] === 0
        if (aFree && bFree) to = random() & 1 ? a : b
        else if (aFree) to = a
        else if (bFree) to = b
        else if (g[i - fall] !== 0) continue
        else {
          // On the surface, nothing below: roll along it, towards a drop.
          const first = random() & 1 ? sideA : sideB
          const second = first === sideA ? sideB : sideA
          const c1 = i + first
          const c2 = i + second
          if (g[c1] === 0 && (g[c1 + fall] === 0 || g[c1 + left] === 0 || g[c1 + right] === 0)) to = c1
          else if (g[c2] === 0 && (g[c2 + fall] === 0 || g[c2 + left] === 0 || g[c2 + right] === 0)) to = c2
          else continue
        }
      }
      g[to] = v
      g[i] = 0
      s[to] = t
      moved++
    }
  }
  return moved
}

/** A shake: every grain thrown somewhere else in the box. */
function toss() {
  const grains: number[] = []
  for (let i = 0; i < grid.length; i++) {
    const v = grid[i]
    if (v !== EMPTY && v !== WALL) {
      grains.push(v)
      grid[i] = EMPTY
    }
  }
  const open: number[] = []
  for (let i = 0; i < grid.length; i++) if (grid[i] === EMPTY) open.push(i)
  for (let k = 0; k < grains.length && open.length; k++) {
    const at = random() % open.length
    grid[open[at]] = grains[k]
    open[at] = open[open.length - 1]
    open.pop()
  }
  settled = false
}

/** Sand poured where a finger is: a little round heap, on empty cells only. */
function pour(cx: number, cy: number, radius: number, colors: string) {
  const x0 = Math.floor(cx / px)
  const y0 = Math.floor(cy / px)
  for (let y = y0 - radius; y <= y0 + radius; y++) {
    for (let x = x0 - radius; x <= x0 + radius; x++) {
      if (x <= 0 || y <= 0 || x >= cols - 1 || y >= rows - 1) continue
      if ((x - x0) * (x - x0) + (y - y0) * (y - y0) > radius * radius) continue
      const i = y * cols + x
      if (grid[i] === EMPTY && random() % 3 !== 0) grid[i] = colorFor(colors, x, y)
    }
  }
  settled = false
}

export function get(app: any, context: any) {
  const W = context.imageWidth || app.frame.width
  const H = context.imageHeight || app.frame.height
  const round = context.round === true
  const fast = app.frame.fast ?? !app.frame.paper
  const s = settings(app)
  const shortSide = Math.min(W, H)
  px = fast ? Math.max(4, Math.round(shortSide / (app.frame.embedded ? 80 : 110))) : Math.max(8, Math.round(shortSide / 30))
  const next = [W, H, px, round, s.colors, s.amount].join(':')
  const now = Date.now()
  if (next !== key || grid.length === 0) {
    key = next
    cols = Math.max(4, Math.floor(W / px))
    rows = Math.max(4, Math.floor(H / px))
    grid = new Uint8Array(cols * rows)
    stamp = new Uint8Array(cols * rows)
    out = new Uint8Array(cols * rows)
    rng = (now ^ 0x5bd1e995) | 1
    buildWalls(round)
    const saved = frameos.recall('sand')
    const at = typeof saved === 'string' ? saved.indexOf('|') : -1
    if (!(at > 0 && saved.slice(0, at) === key && restore(saved.slice(at + 1)))) fill(s.amount, s.colors)
    palette = makePalette(s.colors, fast, app.frame.color !== false)
    startedAt = now
    lastAt = now
    settled = false
    savedSettled = false
  }

  // Which way is down, and how hard.
  const g = accelerometer()
  let gx = 0
  let gy = 1
  if (g) {
    gx = g.x
    gy = g.y
  } else {
    gx = DX[tipped]
    gy = DY[tipped]
  }
  if (tossAsked) {
    tossAsked = false
    toss()
  }
  for (let k = 0; k + 1 < pours.length; k += 2) pour(pours[k], pours[k + 1], fast ? 2 : 1, s.colors)
  pours = []

  // Steps: two a frame on a fast screen (up to five when a frame came
  // late), a dozen a render on e-paper, where a render shows a second of sand.
  const elapsed = now - lastAt
  lastAt = now
  const steps = fast ? Math.max(2, Math.min(5, Math.round(elapsed / 20))) : 12
  // A gentle tip runs slowly, a steep one at full speed.
  const pull = Math.sqrt(gx * gx + gy * gy)
  const chance = Math.max(250, Math.min(1000, Math.round(pull * 1400)))
  let moved = 0
  for (let k = 0; k < steps; k++) {
    const dir = direction(gx, gy)
    if (dir < 0) break
    // Settled sand under the same pull stays settled: check now and then.
    if (settled && dir === lastDir && (tick & 15) !== 0) {
      tick = (tick % 254) + 1
      continue
    }
    lastDir = dir
    moved += step(dir, chance)
  }
  const wasSettled = settled
  settled = moved === 0
  if (settled && !wasSettled && !savedSettled) {
    save()
    savedSettled = true
  }
  if (!settled) savedSettled = false

  // A word for the first seconds on a fast screen: what moves the sand here.
  // (E-paper would keep it until the next refresh.)
  out.set(grid)
  if (fast && now - startedAt < 6000) {
    const hint = g ? 'TILT ME' : 'SWIPE TO TIP'
    const scale = Math.max(1, Math.floor(cols / 40))
    const width = textWidth(hint, scale)
    if (width <= cols - 2) {
      const top = round ? Math.floor(rows * 0.22) : 2
      drawHint(hint, Math.floor((cols - width) / 2), top, scale)
    }
  }

  if (fast) frameos.setNextSleep(settled ? 0.2 : 0)
  else frameos.setNextSleep(settled ? (g ? 2 : 3600) : 0)
  return frameos.pixels(out, palette, { width: cols, height: rows, pixelSize: px })
}

/** The hint over empty cells only, so it never hides a grain. */
function drawHint(text: string, x: number, y: number, scale: number) {
  const before = out.slice(y * cols, (y + 5 * scale) * cols)
  drawText(out, cols, rows, text, x, y, scale, TEXT)
  for (let k = 0; k < before.length; k++) {
    const v = before[k]
    if (v !== EMPTY && v !== WALL) out[y * cols + k] = v
  }
}

// Swipes and keys tip the box where the frame has no accelerometer.
const SWIPE_DIR: Record<string, number> = { down: 0, left: 2, up: 4, right: 6 }
const KEY_DIR: Record<string, number> = { ArrowDown: 0, ArrowLeft: 2, ArrowUp: 4, ArrowRight: 6 }

export function onEvent(app: any, context: any) {
  const p = context.payload || {}
  const e = context.event
  if (e === 'shake') {
    tossAsked = true
    return true
  }
  if (e === 'tilt' || e === 'orientation') {
    // The next render reads the accelerometer: wake for it.
    settled = false
    return true
  }
  if (e === 'pointerDown' || e === 'pointerMove' || e === 'tap') {
    if (e === 'pointerMove' && !p.buttons) return false
    if (typeof p.x === 'number' && typeof p.y === 'number') pours.push(p.x, p.y)
    return true
  }
  if (e === 'swipe' && SWIPE_DIR[p.direction] !== undefined) {
    tipped = SWIPE_DIR[p.direction]
    settled = false
    return true
  }
  if (e === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    if (KEY_DIR[p.code] !== undefined) {
      tipped = KEY_DIR[p.code]
      settled = false
      return true
    }
    if (p.code === 'Space' || p.code === 'Enter') {
      tossAsked = true
      return true
    }
    return false
  }
  if (e === 'button' && p.action === 'press') {
    // The Action key shakes; the arrows turn the box a quarter.
    if (p.role === 'next' || p.role === 'prev') {
      tipped = (tipped + (p.role === 'next' ? 6 : 2)) % 8
      settled = false
      return true
    }
    tossAsked = true
    return true
  }
  return false
}

