// The sand's colors, as frameos.pixels takes them: 0xRRGGBB a palette index.
// 0 is the empty box, 1 to 6 the grains, TEXT the hint and WALL the border
// (and on a round panel everything outside the circle), drawn as the box.
export const TEXT = 254
export const WALL = 255

const SCHEMES: Record<string, { back: number; text: number; grains: number[] }> = {
  // Desert sand in four bands, on a night sky.
  sand: { back: 0x14182b, text: 0x8a93b8, grains: [0xe8c48a, 0xd39a5c, 0xb9733f, 0xf2dcae, 0xe8c48a, 0xd39a5c] },
  rainbow: { back: 0x101010, text: 0x9a9a9a, grains: [0xe5484d, 0xf18f3b, 0xf2cf4a, 0x55b56b, 0x3f8fd8, 0x8b5fd1] },
  snow: { back: 0x0e2a47, text: 0x9fbbd8, grains: [0xffffff, 0xdfeefb, 0xbfdcf5, 0xf4f8ff, 0xffffff, 0xdfeefb] },
}

/**
 * The palette for a scheme. E-paper gets grey and black bands of grains on
 * white, the four greys a grey panel has (a colour one gets its red in a
 * band), so the layers read and the box is not one black slab.
 */
export function makePalette(scheme: string, fast: boolean, color: boolean): Uint32Array {
  const palette = new Uint32Array(256)
  if (!fast) {
    palette.fill(0xffffff)
    const dark = color
      ? [0xaaaaaa, 0x000000, 0xcc0000, 0x555555, 0xaaaaaa, 0x000000]
      : [0xaaaaaa, 0x555555, 0xaaaaaa, 0x000000, 0xaaaaaa, 0x555555]
    for (let i = 0; i < 6; i++) palette[1 + i] = dark[i]
    palette[TEXT] = 0x555555
    return palette
  }
  const s = SCHEMES[scheme] || SCHEMES.sand
  palette.fill(s.back)
  for (let i = 0; i < 6; i++) palette[1 + i] = s.grains[i]
  palette[TEXT] = s.text
  return palette
}
